/**
 * src/ui/assets.ts
 * OWNER: dashboard agent
 *
 * Binary assets that used to be inlined into DASHBOARD_HTML as base64 data
 * URIs, plus the icon set and social image. They live in a separate module so
 * the 833 KB HTML document shrinks to cacheable markup and each asset is
 * served by ui/routes.ts with long cache headers. This mirrors the codebase's
 * embedded-asset idiom (no runtime disk reads; Deno Deploy ships the bundle).
 */

function b64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export interface StaticAsset {
  readonly bytes: Uint8Array;
  readonly contentType: string;
}

function asset(b64: string, contentType: string): StaticAsset {
  return { bytes: b64ToBytes(b64), contentType };
}

